// delegate-bot-rebase: Renovate/Dependabot PRs are handed back to the bot.
const assert = require('node:assert/strict');
const {botKind, run} = require('../actions/auto-rebase/rebase');

const renovateBody = [
  '♻ **Rebasing**: Whenever PR becomes conflicted, or you tick the rebase/retry checkbox.',
  '',
  ' - [ ] <!-- rebase-check -->If you want to rebase/retry this PR, check this box',
  '',
  'This PR was generated by Mend Renovate.'
].join('\n');
const summary = {addHeading() {return this;}, addCodeBlock() {return this;}, async write() {}};

function harness(pr, {comments = [], commitDate = '2026-11-20T09:00:00Z'} = {}) {
  const calls = {bodies: [], comments: [], updates: 0, rebases: 0, failed: false, infos: []};
  const github = {
    rest: {
      pulls: {
        get: async () => ({data: pr}),
        update: async p => {calls.bodies.push(p.body); assert.equal(p.pull_number, pr.number);},
        updateBranch: async () => {calls.updates++;},
        list: 'list'
      },
      issues: {createComment: async p => {calls.comments.push(p.body);}, listComments: 'listComments'},
      git: {getCommit: async p => {assert.equal(p.commit_sha, pr.head.sha); return {data: {committer: {date: commitDate}}};}},
      repos: {compareCommitsWithBasehead: async () => ({data: {behind_by: 2}})}
    },
    paginate: async fn => {if (fn === 'list') return [{number: pr.number}]; assert.equal(fn, 'listComments'); return comments;}
  };
  const core = {summary, info: m => calls.infos.push(m), warning() {}, setFailed() {calls.failed = true;}};
  const go = opts => run({github, context: {repo: {owner: 'o', repo: 'r'}}, core, numbers: String(pr.number), token: 't',
    rebase: () => {calls.rebases++; return {ok: false, files: ['pnpm-workspace.yaml'], message: 'Rebase conflicts (aborted):\n- pnpm-workspace.yaml'};}, ...opts});
  return {calls, go};
}
const base = {state: 'open', mergeable: false, mergeable_state: 'dirty', base: {ref: 'main', repo: {full_name: 'o/r'}}};
const renovate = {...base, number: 424, user: {login: 'renovate[bot]'}, body: renovateBody, head: {sha: 'aaa', ref: 'renovate/x', repo: {full_name: 'o/r'}}};
const dependabot = {...base, number: 7, user: {login: 'dependabot[bot]'}, body: 'Bumps x', head: {sha: 'bbb', ref: 'dependabot/x', repo: {full_name: 'o/r'}}};

(async () => {
  assert.equal(botKind(renovate), 'renovate');
  assert.equal(botKind(dependabot), 'dependabot');
  assert.equal(botKind({...renovate, user: {login: 'someone'}}), null);
  assert.equal(botKind({...renovate, body: 'no checkbox'}), null);

  // Off by default: unchanged behavior (rebase attempted, conflict fails the job).
  let h = harness(renovate);
  await h.go({mode: true});
  assert.equal(h.calls.rebases, 1);
  assert.equal(h.calls.failed, true);
  assert.equal(h.calls.bodies.length, 0);

  // Renovate, dirty: only the checkbox is ticked; no rebase, no failure, no success comment.
  h = harness(renovate);
  await h.go({mode: true, delegateBots: true});
  assert.equal(h.calls.rebases, 0);
  assert.equal(h.calls.failed, false);
  assert.equal(h.calls.comments.length, 0);
  assert.deepEqual(h.calls.bodies, [renovateBody.replace(' - [ ] <!--', ' - [x] <!--')]);
  assert.match(h.calls.infos.join('\n'), /Delegated to Renovate/);

  // Already ticked: nothing to edit, still delegated.
  h = harness({...renovate, body: renovateBody.replace('[ ]', '[x]')});
  await h.go({mode: true, delegateBots: true});
  assert.equal(h.calls.bodies.length, 0);
  assert.equal(h.calls.failed, false);
  assert.match(h.calls.infos.join('\n'), /already ticked/);

  // Behind Renovate PR: delegated instead of a github-actions merge commit (which makes Renovate stop managing it).
  h = harness({...renovate, mergeable: true, mergeable_state: 'behind'});
  await h.go({delegateBots: true});
  assert.equal(h.calls.updates, 0);
  assert.equal(h.calls.bodies.length, 1);

  // Unstable and behind: delegated too.
  h = harness({...renovate, mergeable: true, mergeable_state: 'unstable'});
  await h.go({delegateBots: true});
  assert.equal(h.calls.updates, 0);
  assert.equal(h.calls.bodies.length, 1);

  // Clean bot PR: nothing happens.
  h = harness({...renovate, mergeable: true, mergeable_state: 'clean'});
  await h.go({delegateBots: true});
  assert.equal(h.calls.bodies.length, 0);
  assert.equal(h.calls.updates, 0);

  // Report-conflicts sweeps also delegate instead of commenting conflict lists.
  h = harness(renovate);
  await h.go({report: true, numbers: '', delegateBots: true});
  assert.equal(h.calls.bodies.length, 1);
  assert.equal(h.calls.comments.length, 0);

  // Dependabot: one "@dependabot rebase" comment per head commit.
  h = harness(dependabot);
  await h.go({mode: true, delegateBots: true});
  assert.deepEqual(h.calls.comments, ['@dependabot rebase']);
  assert.equal(h.calls.failed, false);
  assert.equal(h.calls.rebases, 0);
  h = harness(dependabot, {comments: [{body: '@dependabot rebase', created_at: '2026-11-20T10:00:00Z'}]});
  await h.go({mode: true, delegateBots: true});
  assert.equal(h.calls.comments.length, 0);
  assert.match(h.calls.infos.join('\n'), /already requested/);
  // An older command (before the current head commit) does not count.
  h = harness(dependabot, {comments: [{body: '@dependabot rebase', created_at: '2026-11-19T10:00:00Z'}]});
  await h.go({mode: true, delegateBots: true});
  assert.deepEqual(h.calls.comments, ['@dependabot rebase']);

  // Renovate PR without the checkbox: falls back to the normal path.
  h = harness({...renovate, body: 'Renovate PR with rebase disabled <!-- rebase-check --> removed'.replace('<!-- rebase-check -->', '')});
  await h.go({mode: true, delegateBots: true});
  assert.equal(h.calls.rebases, 1);

  // Human PRs are never delegated.
  h = harness({...renovate, user: {login: 'atherdon'}});
  await h.go({mode: true, delegateBots: true});
  assert.equal(h.calls.rebases, 1);
  assert.equal(h.calls.bodies.length, 0);
  console.log('auto-rebase delegate-bot-rebase tests: ok');
})().catch(e => {console.error(e); process.exitCode = 1;});
